SELECT A3 AS branch_location, A2 AS district_name
FROM district
WHERE A13 = (SELECT MAX(A13) FROM district);

SELECT COUNT(*) FROM atom AS a
INNER JOIN molecule AS m ON a.molecule_id = m.molecule_id
WHERE m.label = 'TR008' AND LOWER(a.element) = 'c';

SELECT DISTINCT subtypes AS type FROM cards WHERE availability = 'arena'
UNION
SELECT DISTINCT supertypes AS type FROM cards WHERE availability = 'arena';

SELECT 100.0 * SUM(isOnlineOnly) / COUNT(*) AS percentage
FROM cards
WHERE frameEffects = 'legendary';

SELECT COUNT(*)
FROM cards
WHERE borderColor = 'borderless' AND edhrecRank > 12000;

SELECT EXISTS (
  SELECT 1
  FROM cards c
  INNER JOIN foreign_data fd ON c.uuid = fd.uuid
  WHERE c.name = 'Ancestor''s Chosen' AND fd.language = 'Korean'
) AS has_korean_version;

SELECT cards.name FROM cards
INNER JOIN sets ON cards.setCode = sets.code
WHERE sets.name = 'Coldsnap' AND cards.number = '4';

SELECT COUNT(*) FROM (
  SELECT UserId FROM badges WHERE UserId IS NOT NULL GROUP BY UserId HAVING COUNT(*) > 5
)

SELECT COUNT(*)
FROM posts
WHERE ViewCount > (
    SELECT AVG(ViewCount) FROM posts
);

SELECT CASE WHEN EXISTS (
  SELECT 1 FROM Patient p
  JOIN Laboratory l ON p.ID = l.ID
  WHERE p.ID = 57266
    AND ((p.SEX = 'M' AND l.UA > 8.0) OR (p.SEX = 'F' AND l.UA > 6.5))
) THEN 'Yes' ELSE 'No' END AS within_normal_range;

SELECT COUNT(*) FILTER (WHERE LOWER(Segment) = 'sme' AND Currency = 'CZK') - 
       COUNT(*) FILTER (WHERE LOWER(Segment) = 'sme' AND Currency = 'EUR') AS MoreSMEs
FROM customers;
